-- SEO article seed
insert into public.luma_blog_posts(workspace_id,slug,title,excerpt,content_html,category,cover_image_url,seo_title,seo_description,seo_keywords,status,published_at,author_name,video_embed_url,image_alt,content_type,tags,is_featured,is_global,reading_minutes,faq_json)
values(null,'cara-upload-data-affiliate-tanpa-bikin-dashboard-kacau','Cara Upload Data Affiliate Tanpa Bikin Dashboard Kacau','Panduan aman mengimpor data affiliate memakai Mapping Wizard, preview, dan Data Health sebelum membaca dashboard.','<h2>Mulai dari struktur, bukan dari tombol upload</h2><p>Masalah upload sering bukan terjadi karena file rusak, tetapi karena nama kolom berubah atau definisi metrik berbeda. Karena itu Lumaway memisahkan proses menjadi Upload, Mapping, Preview, lalu Import.</p><h2>Periksa identitas creator dan metrik utama</h2><p>Pastikan minimal ada identitas creator seperti username atau Affiliate ID serta salah satu metrik GMV, Qty, Orders, atau Commission. Mapping wajib yang kosong akan menghentikan proses sebelum data ditulis.</p><h2>Gunakan preview sebagai pemeriksaan terakhir</h2><p>Lihat beberapa row pertama dan pastikan angka masuk ke field yang benar. Jika hasilnya janggal, perbaiki mapping sebelum menekan Import Data.</p><h2>Tutup dengan Data Health</h2><p>Setelah import, buka Data Health untuk mengecek row tanpa creator, row dengan seluruh metrik nol, duplicate identity, serta masalah mapping produk.</p>','Tutorial Lumaway','/insights/01-cara-upload-data-affiliate-tanpa-bikin-dashboard-kacau.svg','Cara Upload Data Affiliate Tanpa Bikin Dashboard Kacau','Panduan aman mengimpor data affiliate memakai Mapping Wizard, preview, dan Data Health sebelum membaca dashboard.',array['upload data affiliate','mapping data','lumaway'],'published',now(),'Lumaway',null,'Cara Upload Data Affiliate Tanpa Bikin Dashboard Kacau','article',array['upload data affiliate','mapping data','lumaway'],true,true,4,'[]'::jsonb)
