values(null,'cara-mengelola-database-creator','Cara Mengelola Database Creator agar Tidak Penuh Duplikasi','Prinsip identity management untuk username, affiliate ID, social profile, ratecard, dan histori creator.','<h2>Gunakan identitas yang stabil</h2><p>Nama display dapat berubah. Prioritaskan username, Affiliate ID, platform, dan link profil yang dapat diverifikasi.</p><h2>Pisahkan kandidat duplicate dari keputusan merge</h2><p>Creator Identity Center menampilkan confidence dan linked data agar user dapat membandingkan record sebelum memilih canonical creator.</p><h2>Jangan merge identity sampah</h2><p>Nilai seperti kosong, --, N/A, atau unknown harus dipisahkan karena banyak creator berbeda dapat jatuh ke key yang sama jika data sumber buruk.</p>','Affiliate & Creator','/insights/04-cara-mengelola-database-creator.svg','Cara Mengelola Database Creator agar Tidak Penuh Duplikasi','Prinsip identity management untuk username, affiliate ID, social profile, ratecard, dan histori creator.',array['database creator','creator identity','duplicate creator'],'published',now(),'Lumaway',null,'Cara Mengelola Database Creator agar Tidak Penuh Duplikasi','article',array['database creator','creator identity','duplicate creator'],true,true,3,'[]'::jsonb)
