values(null,'customer-360-untuk-tim-affiliate','Customer 360 untuk Tim Affiliate: Apa yang Perlu Dilihat?','Cara memakai Customer 360 sebagai pusat konteks creator tanpa memindahkan data antar spreadsheet.','<h2>Mulai dari profil creator</h2><p>Periksa identity, platform, social profile, ratecard dan informasi kontak sebelum membaca performa.</p><h2>Baca timeline lintas aktivitas</h2><p>Listing, sample, shipping, campaign, task, ratecard dan performance menjadi lebih berguna ketika disusun berdasarkan waktu.</p><h2>Jaga hubungan antara data dan tindakan</h2><p>Setelah menemukan pola, catat follow up atau task agar insight tidak berhenti sebagai angka.</p>','Product Knowledge','/insights/05-customer-360-untuk-tim-affiliate.svg','Customer 360 untuk Tim Affiliate: Apa yang Perlu Dilihat?','Cara memakai Customer 360 sebagai pusat konteks creator tanpa memindahkan data antar spreadsheet.',array['customer 360','creator 360','affiliate crm'],'published',now(),'Lumaway',null,'Customer 360 untuk Tim Affiliate: Apa yang Perlu Dilihat?','article',array['customer 360','creator 360','affiliate crm'],false,true,3,'[]'::jsonb)
