values(null,'campaign-tracker-affiliate','Cara Menjalankan Campaign Affiliate dengan Tracker yang Rapi','Kerangka campaign dari target, creator, banner, deliverable, sample, shipping sampai hasil.','<h2>Definisikan target dan periode</h2><p>Tentukan objective, platform, target GMV/order, budget, start date dan end date sebelum campaign berjalan.</p><h2>Hubungkan creator dan deliverable</h2><p>Setiap creator perlu memiliki content type, due date, stage, sample/shipping, dan target yang bisa dipantau.</p><h2>Evaluasi target vs actual</h2><p>Setelah campaign berjalan, baca deliverable progress bersama GMV, order, commission dan biaya pendukung.</p>','Campaign & Promotion','/insights/07-campaign-tracker-affiliate.svg','Cara Menjalankan Campaign Affiliate dengan Tracker yang Rapi','Kerangka campaign dari target, creator, banner, deliverable, sample, shipping sampai hasil.',array['campaign affiliate','campaign tracker','influencer'],'published',now(),'Lumaway',null,'Cara Menjalankan Campaign Affiliate dengan Tracker yang Rapi','article',array['campaign affiliate','campaign tracker','influencer'],false,true,3,'[]'::jsonb)
