values(null,'cara-membaca-tren-performa','Cara Membaca Tren Performa Tanpa Tertipu Angka Harian','Prinsip membaca time-series GMV, order, qty, commission, dan metrik lain secara lebih kontekstual.','<h2>Pilih periode yang sesuai</h2><p>Perubahan harian dapat terlihat dramatis pada periode pendek. Gunakan rentang yang relevan dengan siklus campaign dan aktivitas bisnis.</p><h2>Bedakan level dan perubahan</h2><p>Nilai hari ini dan persentase perubahan menjawab pertanyaan berbeda. Selalu periksa basis pembanding.</p><h2>Cari konteks di bawah grafik</h2><p>Gunakan ranking creator, product ranking, campaign, dan event operasional untuk memahami perubahan yang terlihat pada chart.</p>','Data & Analytics','/insights/08-cara-membaca-tren-performa.svg','Cara Membaca Tren Performa Tanpa Tertipu Angka Harian','Prinsip membaca time-series GMV, order, qty, commission, dan metrik lain secara lebih kontekstual.',array['trend chart','time series','gmv harian'],'published',now(),'Lumaway',null,'Cara Membaca Tren Performa Tanpa Tertipu Angka Harian','article',array['trend chart','time series','gmv harian'],false,true,3,'[]'::jsonb)
