values(null,'social-profile-creator-di-listings','Social Profile Creator di Listings: Kenapa Perlu?','Cara menghubungkan Instagram, TikTok, Facebook, Lemon8, YouTube, Threads, dan X ke Master Creator.','<h2>Satu creator dapat aktif di banyak platform</h2><p>Link sosial membantu tim membuka profil yang benar tanpa mencari ulang username.</p><h2>Foto profil mempermudah scanning</h2><p>Lumaway mencoba membaca foto dari metadata publik. Jika platform membatasi akses, user tetap dapat menyimpan link dan menggunakan Avatar URL manual.</p><h2>Simpan di Master Creator</h2><p>Social profile berada pada identity creator sehingga dapat dipakai lintas listing dan workflow lain.</p>','Product Knowledge','/insights/19-social-profile-creator-di-listings.svg','Social Profile Creator di Listings: Kenapa Perlu?','Cara menghubungkan Instagram, TikTok, Facebook, Lemon8, YouTube, Threads, dan X ke Master Creator.',array['social profile creator','listings','affiliate crm'],'published',now(),'Lumaway',null,'Social Profile Creator di Listings: Kenapa Perlu?','article',array['social profile creator','listings','affiliate crm'],false,true,3,'[]'::jsonb)
