values(null,'dari-upload-ke-keputusan','Dari Upload File sampai Keputusan: Alur Kerja Data yang Lebih Sehat','Sebuah workflow praktis: upload, validasi, analisis, keputusan, action, lalu review.','<h2>Upload bukan akhir pekerjaan</h2><p>Data perlu dipetakan, dipreview, dan diperiksa kesehatannya sebelum dipakai sebagai dasar diskusi.</p><h2>Analisis perlu pertanyaan</h2><p>Gunakan dashboard untuk menjawab pertanyaan tertentu, bukan untuk mencari makna dari semua angka sekaligus.</p><h2>Hubungkan insight ke action</h2><p>Campaign Tracker, Listings, Kanban, Sample dan Shipping memberi tempat agar keputusan dapat diteruskan menjadi aktivitas.</p><h2>Review membentuk pengetahuan</h2><p>Catat hasil setelah tindakan dilakukan. Dengan begitu, tim tidak hanya menyimpan data, tetapi membangun pembelajaran operasional.</p>','Business & Growth','/insights/20-dari-upload-ke-keputusan.svg','Dari Upload File sampai Keputusan: Alur Kerja Data yang L...','Sebuah workflow praktis: upload, validasi, analisis, keputusan, action, lalu review.',array['data workflow','business decision','lumaway'],'published',now(),'Lumaway',null,'Dari Upload File sampai Keputusan: Alur Kerja Data yang Lebih Sehat','article',array['data workflow','business decision','lumaway'],false,true,4,'[]'::jsonb)
